<?php
require_once __DIR__ . '/config/conexion.php';
require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){
 post_only();$uid=(int)($_POST['id_usuario']??0);$lid=(int)($_POST['id_libro']??0);$fp=trim($_POST['fecha_prestamo']??'');$fd=trim($_POST['fecha_devolucion']??'');
 if(!$uid||!$lid||!valid_date($fp)||!valid_date($fd)||$fd<$fp){flash('error','Selecciona usuario, libro y fechas válidas; la devolución no puede ser anterior al préstamo.');}
 else{try{$pdo->beginTransaction();$u=$pdo->prepare('SELECT id_usuario FROM usuarios WHERE id_usuario=?');$u->execute([$uid]);if(!$u->fetch())throw new RuntimeException('El usuario seleccionado no existe.');$l=$pdo->prepare('SELECT estado FROM libros WHERE id_libro=? FOR UPDATE');$l->execute([$lid]);$book=$l->fetch();if(!$book||$book['estado']!=='Disponible')throw new RuntimeException('El libro ya no está disponible. Actualiza la página e inténtalo con otro.');$pdo->prepare("INSERT INTO prestamos(id_usuario,id_libro,fecha_prestamo,fecha_devolucion,estado_prestamo) VALUES(?,?,?,?,'Activo')")->execute([$uid,$lid,$fp,$fd]);$pdo->prepare("UPDATE libros SET estado='Prestado' WHERE id_libro=?")->execute([$lid]);$pdo->commit();flash('success','Préstamo registrado.');}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();flash('error',$ex instanceof RuntimeException?$ex->getMessage():'No se pudo registrar el préstamo.');}}
 header('Location: prestamos.php');exit;
}
$users=$pdo->query('SELECT id_usuario,nombre FROM usuarios ORDER BY nombre')->fetchAll();$books=$pdo->query("SELECT id_libro,titulo FROM libros WHERE estado='Disponible' ORDER BY titulo")->fetchAll();$loans=$pdo->query("SELECT p.*,u.nombre usuario,l.titulo libro,IF(p.estado_prestamo='Activo' AND p.fecha_devolucion<CURDATE(),'Atrasado',p.estado_prestamo) estado_vista FROM prestamos p JOIN usuarios u ON u.id_usuario=p.id_usuario JOIN libros l ON l.id_libro=p.id_libro ORDER BY p.id_prestamo DESC")->fetchAll();
page_start('Préstamos','prestamos.php');
?>
<div class="page-heading"><div><span class="eyebrow">CIRCULACIÓN</span><h1>Préstamos</h1><p>Presta libros disponibles y consulta los registros.</p></div></div>
<section class="panel mb-4"><h2>Nuevo préstamo</h2><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()); ?>"><div class="col-md-3"><label class="form-label">Usuario</label><select class="form-select" name="id_usuario" required><option value="">Seleccionar</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id_usuario']; ?>"><?= e($u['nombre']); ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Libro disponible</label><select class="form-select" name="id_libro" required><option value="">Seleccionar</option><?php foreach($books as $b): ?><option value="<?= (int)$b['id_libro']; ?>"><?= e($b['titulo']); ?></option><?php endforeach; ?></select><?php if(!$books): ?><small class="text-danger">No hay libros disponibles.</small><?php endif; ?></div><div class="col-md-2"><label class="form-label">Fecha préstamo</label><input class="form-control" type="date" name="fecha_prestamo" required value="<?= e(date('Y-m-d')); ?>"></div><div class="col-md-2"><label class="form-label">Fecha devolución</label><input class="form-control" type="date" name="fecha_devolucion" required value="<?= e(date('Y-m-d',strtotime('+14 days'))); ?>"></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary w-100">Crear</button></div></form></section>
<section class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Usuario</th><th>Libro</th><th>Préstamo</th><th>Devolución</th><th>Estado</th></tr></thead><tbody><?php foreach($loans as $p): ?><tr><td><?= e($p['usuario']); ?></td><td><?= e($p['libro']); ?></td><td><?= e($p['fecha_prestamo']); ?></td><td><?= e($p['fecha_devolucion']); ?></td><td><span class="badge rounded-pill text-bg-<?= $p['estado_vista']==='Atrasado'?'danger':($p['estado_vista']==='Devuelto'?'success':'warning'); ?>"><?= e($p['estado_vista']); ?></span></td></tr><?php endforeach; ?><?php if(!$loans): ?><tr><td colspan="5" class="text-center text-secondary py-4">No hay préstamos registrados.</td></tr><?php endif; ?></tbody></table></div></section>
<?php page_end(); ?>
